-- 2026-09-23 사용자 지시: 프로필이 달라도 글이 같은 사람처럼 읽힌다.
-- 오늘 올라간 27건을 프로필 캐릭터(말투·나이·성별 성향)에 맞춰 다시 쓴다. 사실과 수치는 유지한다.
-- 반복 상한: 도시별 하루 5건 중 '확인하라'류 최대 1건, 질문으로 끝나는 글 최대 2건.
begin;

update public.posts post
set body = fix.body
from (values
-- CALGARY
('423b3cda-fece-4d72-a3b7-c9f2c7af07b2'::uuid, E'캘거리 요금 종류가 한 번, 하루, 월간으로 나뉘어 있음\n카드도 되고 앱으로도 됨\n나는 아직 뭐가 제일 싼지 계산 안 해봄\n너네는 카드 삼, 앱 삼?'),
('6f2a99a1-2029-4081-8998-a9b81dac5020'::uuid, E'캘거리 도서관 카드는 무료고 온라인으로도 만듦\n전자책이랑 프로그램까지 같이 열려서 정착 초반에 만들어두면 쓸 일이 많음\n나는 만들고 한 달 뒤에 처음 씀'),
('4f39420e-6e45-47bd-92a5-acf0a7163253'::uuid, E'첫 가을이라 낙엽이랑 마당 쓰레기를 어디 버리는지 몰라서 그냥 세워뒀음\n알고 보니 마당 쓰레기는 따로 처리하고, 지금 시즌엔 에코센터에 무료로 가져갈 수 있대 (9월 18일부터 10월 31일까지)\n기간은 해마다 달라짐\n이거 몰라서 버린 사람 나뿐인가'),
('0d08ee74-721b-4264-9cb2-ab040f645e31'::uuid, E'컨페더레이션 공원이 160헥타르가 넘고 습지도 8헥타르쯤 된다고 함\n1967년 연방 100주년 기념으로 만든 공원이라는데 그건 처음 알았음\n넓어서 어디로 들어가느냐에 따라 걷는 길이 완전히 달라짐\n슬로프 쪽으로 들어가는 사람 있음?'),
('ff32d60d-47ef-4e9c-a194-c1755556c469'::uuid, E'축제 때만 가던 프린스아일랜드인데 요즘은 평일 점심에 걷으러 감\n다운타운 한가운데 섬이고 캐나다데이 같은 큰 행사가 여기서 열림\n행사 날엔 사람이 많아서 그날은 피하는 편'),
('4ec16796-6877-4e4e-9865-9d1ab31caaa4'::uuid, E'보우강만 걷는 줄 알았는데 도시 전체가 길로 이어져 있더라\n캘거리 경로망이 북미에서 제일 넓고 시가 관리하는 구간만 1000km라고 함\n걷는 사람, 자전거, 뛰는 사람이 다 같이 쓰니까 오른쪽으로 붙어 다님'),
('33cfe245-3c5e-436c-a5aa-5418c39085c4'::uuid, E'10월부터 Park & Ride 무료 자리 일부가 예약 주차로 바뀐대\n브렌트우드, 달하우지, 터스카니, 서머싯브리들우드가 대상임\n무료 자리는 남아 있긴 한데 있으면 쓰는 방식이래\n역까지 차 갖고 가는 사람은 자리 남은 걸 보고 나가야 함'),
-- EDMONTON
('caff757f-b17d-4546-a43d-43e37007c2c4'::uuid, E'헨데이가 그냥 큰 도로인 줄 알았는데 도시를 한 바퀴 도는 순환도로였음\n80km짜리라서 한 바퀴 다 돌면 하루 다 감\n첫 달엔 진입로를 세 번 놓쳤고 아직도 가끔 놓침'),
('ebd3b931-d6b8-4da8-a595-38e6b49ece49'::uuid, E'이사 첫 달엔 강아지 목줄 풀 데가 어디인지 몰라서 골목만 돌았음\n알고 보니 개 풀어놓는 구역이 60곳이 넘고 리버밸리 쪽에 몰려 있대\n구역마다 규칙이 다르다는 건 나중에 알았음\n단골로 정한 코스 있으면 알려주면 좋겠음'),
('5acb438c-7313-4897-860d-d9218d085a51'::uuid, E'주말에 엘크아일랜드 간다고 길만 검색하고 나갈 뻔했음 (입장료 확인 안 함, 늘 이럼)\n80km 넘는 트레일이랑 호수가 있고 들소, 엘크, 새 250종 넘게 산대\n평일이나 아침 일찍이 한산하다고 함\n들소 봤다는 사람 있음?'),
('addb3385-a4de-4cf4-93cf-3826540d9d9f'::uuid, E'제스퍼 애비뉴에 차 세워놓고 두 시간 뒤에 EPark 표시를 봄 (그동안 요금 안 내고 있었음)\n에드먼튼 주차는 EPark 구역, 이벤트 제한, 월 주차, 거주자 주차로 나뉨\n다운타운은 시간대별로 규칙이 달라짐\n나 같은 사람 또 있겠지'),
('85dd0c11-8040-48fc-a435-a2b85a339c88'::uuid, E'겨울엔 나가기 전에 511 봄\n도로 상황이 실시간으로 나옴\n너네는 뭐 보고 나감?'),
-- MONTREAL
('9667da5c-fa7e-43bb-9912-61c220d46a27'::uuid, E'주말마다 에코센터 가는 차에 꼭 소파나 가구가 실려 있음\n거긴 재활용품, 공사 자재, 위험 폐기물, 큰 물건까지 받음\n상태 괜찮은 건 기부로 돌리기도 하고, 정원 쓰레기는 여름철만 받음\n저기 가본 사람 있음?'),
('3046907e-3b51-499b-a5cd-508b36687b5d'::uuid, E'몇 년 살았는데 불어는 아직 메뉴 읽는 수준임 (나만 그런 줄 알았음)\n16살 넘으면 무료 프랑스어 강좌를 들을 수 있고 조건이 되면 생활비 지원도 나온대\n몇 년 지나서 알았음. 좀 아까움'),
('f223dd5b-57e8-4d31-a56a-bba6c97b8bad'::uuid, E'몬트리올에서 공원 하나만 꼽으라면 다들 몽루아얄을 말함\n아침 6시부터 밤 12시까지 열고 비버 호수, 전망대, 산책로가 다 있음\n올라가는 길이 여러 개라 첫 방문엔 어디로 올라갈지가 제일 고민임\n다들 어느 코스로 올라감?'),
('03efc74b-a22f-4944-84ce-211d312f8c5a'::uuid, E'올드포트 시계탑이 그냥 배경인 줄 알았는데 1차 세계대전 때 바다에서 잃은 선원들 기리는 탑이었음\n1919년부터 1922년 사이에 세웠다고 함\n현장은 오전 6시부터 자정까지 열려 있음\n이제는 볼 때마다 좀 다르게 보임'),
('aa5d971b-8de1-4dd8-9357-d93ea98ef5ef'::uuid, E'주말에 장 보러 가면 장탈롱부터 떠오름\n리틀이탈리 한복판에 있고 1933년 5월에 문을 연, 몬트리올에서 제일 오래된 시장 중 하나임\n연중 열려서 겨울에도 생산자 물건을 볼 수 있음\n계절마다 파는 게 달라서 갈 때마다 다름'),
-- TORONTO
('b7b7067b-daa2-4f1b-9ae0-b464599372c3'::uuid, E'톰슨 공원 안에 옛집들이 있는 건 알았는데 그게 스카보로 뮤지엄인 줄은 몰랐음\n문화유산 건물 네 채가 모여 있다고 함\n산책하다 들르기 딱 좋음\n동네 과거 얘기가 이렇게 모여 있는 줄 몰랐음'),
('96627599-731a-4fd7-b82f-4a2afb7a58ee'::uuid, E'면허 갱신하러 센터까지 갔는데 집에서 되는 거였음 (줄 서서 기다린 시간이 아까움)\n운전면허, 헬스카드 갱신 같은 게 온라인으로 되고, 안 되면 가까운 곳 약속을 잡음\n다음엔 검색부터 할 예정임'),
('fb24981e-e5e6-4cac-ac4f-9a162c301a07'::uuid, E'하버프론트 걷다가 자전거 전용 구간으로 들어가서 한참을 뛰어야 했음 (다들 봄 ㅋㅋ)\n토론토 트레일은 걷는 사람, 자전거, 인라인 다 같이 쓰는 길임\n포장된 데랑 아닌 데가 섞여 있음\n하버프론트 자주 걷는 사람, 어디가 편함?'),
('6b09f714-7966-46cc-bc47-a8e8af8ccd8a'::uuid, E'나이아가라 기차가 주말에만 있는 줄 알았는데 평일에도 다님\n토론토랑 나이아가라폴스 사이를 연중 운행하고, 기차 없는 시간엔 레이크쇼어웨스트로 벌링턴까지 간 뒤 버스로 갈아탐\n평일이 한가할지 주말이 나을지 아직 못 정했음'),
('1fb60e7c-a867-494e-800c-30e4495e590b'::uuid, E'브램턴에서 토론토로 출근하게 돼서 요금부터 찾아봄\n어른·청소년·학생 종류가 있고 거리로 정해지며 12살 이하는 무료임\n프레스토, 신용카드, 전자 티켓 다 됨\n첫 주에 뭘로 타야 덜 헤맬지 고민 중임'),
-- VANCOUVER
('b240afe1-f697-455c-9ad7-56aed32039ca'::uuid, E'오크리지 분관에 책 반납하러 갔는데 문이 닫혀 있었음\n새 분관 준비 때문에 닫았고 2027년에 연다고 함\n그래서 요즘은 가까운 다른 분관 씀\n분관마다 여는 시간이 달라서 나가기 전에 보게 됨'),
('a2a98e0d-a588-4332-91b3-f185fb550ece'::uuid, E'컴패스 카드에 환불되는 보증금이 붙는 것 같음\n파는 곳도 정해져 있는 듯한데 정확한 목록까지는 못 봄\n금액은 바뀐다고 하니까 안내를 보는 게 맞을 듯\n다들 충전은 어디서 함?'),
('8f7d0ec8-0059-4688-b533-7f14878cb43f'::uuid, E'집 앞에 자리가 없어서 두 블록 옆에 세웠는데 우리 구역이 아니었음\n밴쿠버 주차 허가증은 집 주소 구역에서만 유효해서 웨스트엔드 딱지로 마운트플레전트엔 못 세움\n차 번호가 등록돼 있고 딱지를 앞유리에 붙여야 유효함 (이사 후 갱신을 깜빡했음)\n이사하면 갱신부터 챙겨야 함'),
('09de0fd0-bd92-43dd-b6c1-9670e801daea'::uuid, E'출근 시간에 접이식 자전거 접어서 스카이트레인 타는 사람을 자주 봄\n자전거는 버스, 스카이트레인, 씨버스, 웨스트코스트 익스프레스까지 거의 다 실을 수 있음\n시간대 규칙이 따로 있을 수 있음\n자전거 들고 대중교통 타는 사람 여기 있음?'),
('030f5562-66f1-41a0-8021-54def0f93efd'::uuid, E'밴쿠버 온 지 얼마 안 됐을 땐 커뮤니티센터 문턱이 높게 느껴졌음\nFlexipass라는 게 있어서 체육관이랑 수영장을 한 패스로 쓴다고 함\n드롭인 프로그램도 들어가는데 자리랑 사전 등록은 상황마다 다름\n한 달 요금이 붙어서 금액은 확인이 필요함\n센터 처음 갈 때 뭐부터 해야 하는지 아직 파악 중임')
) as fix(id, body)
where post.id = fix.id;

select count(*) as rewritten from public.posts
where id in (select id from public.posts where created_at > now() - interval '20 hours') and body not like '%확인해라%';
commit;
